      'romcom-limiting-belief',
      'longing-need-wound-mask-profile',
      'lead-short-term-goal-stakes',
      'broken-beginning-wound-mask-essence',
      'hero-want-need-objective',
      'wound-tied-to-premise'
    ],
    array['JanitorAI', 'SillyTavern', 'MarinaraTavern']
  ),
