    ],
    array['JanitorAI', 'SillyTavern', 'MarinaraTavern']
  ),
  (
    'core-motif-theme-image-bank-map',
    'Motif Theme Image Bank Map',
    'motif-theme-image-bank-map',
    'Theme and symbol taxonomy',
