-- - Legacy DOC, roughly 5.4k extracted words.
-- - The source sorts affairs into accidental infidelity, crisis-romantic affairs,
--   marital arrangements, philandering, revenge/power affairs, and gendered aftermath claims.
-- - These seeds preserve useful typology and character-belief material. Older gender generalizations,
--   shaming labels, and moral certainty are modernized, softened, and routed as belief-source
--   or character-worldview evidence rather than truth-source guidance.

insert into public.category_tags (id, group_name, label, slug, description)
values
  (
    'tag-infidelity-typology-source',
    'relationship_dynamic',
    'Infidelity Typology Source',
    'infidelity-typology-source',
    'Affair categories, motive patterns, secrecy structures, blame stories, and post-betrayal consequence maps.'
  ),
  (
    'tag-accidental-infidelity-risk-zone',
    'relationship_dynamic',
    'Accidental Infidelity Risk Zone',
    'accidental-infidelity-risk-zone',
    'Travel, alcohol, loneliness, flattery, peer modeling, blurred boundaries, politeness pressure, and bad-day vulnerability.'
  ),
  (
    'tag-romantic-affair-crisis-flight',
    'relationship_dynamic',
    'Romantic Affair as Crisis Flight',
    'romantic-affair-crisis-flight',
    'Life-transition affairs framed as escape from depression, aging, failure, grief, parenthood, pressure, or unwanted reality.'
  ),
  (
    'tag-affair-as-depression-escape',
    'relationship_dynamic',
    'Affair as Depression Escape',
    'affair-as-depression-escape',
    'Using intensity, rescue fantasy, sexual novelty, or romantic fixation to feel alive instead of treating pain directly.'
  ),
  (
    'tag-marital-arrangement-encapsulation',
    'relationship_dynamic',
    'Marital Arrangement Encapsulation',
    'marital-arrangement-encapsulation',
    'A parallel relationship used to stabilize a distant marriage while keeping the core problem sealed off and unsolved.'
  ),
  (
    'tag-philandering-gender-power-script',
    'belief_source',
    'Philandering Gender-Power Script',
    'philandering-gender-power-script',
    'Belief-source frame for compulsive conquest, masculinity or femininity proof, gender resentment, entitlement, and status performance.'
  ),
  (
    'tag-revenge-affair-power-restoration',
    'relationship_dynamic',
    'Revenge Affair and Power Restoration',
    'revenge-affair-power-restoration',
    'Affairs used to retaliate, restore damaged pride, punish a rival, feel chosen, or make someone else lose what the character lost.'
  ),
  (
    'tag-affair-partner-rescue-fantasy',
    'relationship_dynamic',
    'Affair Partner Rescue Fantasy',
    'affair-partner-rescue-fantasy',
    'Damsel/rescuer dynamics, crisis bonding, dependency, heroic self-image, chaos addiction, and being needed as erotic proof.'
  ),
  (
    'tag-lying-primary-betrayal-injury',
    'relationship_dynamic',
    'Lying as Primary Betrayal Injury',
    'lying-primary-betrayal-injury',
    'The trust wound created by secrecy, denial, withheld truth, adversarial partnership, and reality distortion after an affair.'
  ),
  (
    'tag-child-secret-triangulation',
    'content_boundary',
    'Child Secret Triangulation',
    'child-secret-triangulation',
    'Involving children in affair secrecy, message relaying, divided loyalty, cover stories, or parentification after betrayal.'
  ),
  (
